  "Data_Saver_Notice": {
    "de-DE": "Wenn „Niedriger Datenverbrauch“ ausgewählt wurde, werden Videos nicht automatisch abgespielt. Wenn „Nicht erlauben“ ausgewählt wurde, werden Videos nicht geladen.\n\nBei Verwendung einer WLAN-Verbindung werden die Funktionen nicht eingeschränkt.",
    "en-GB": "If \"Low Data\" is selected, videos will not play automatically. If \"Don't Allow\" is selected, videos will not load.\n\nFeatures will not be restricted when using a Wi-Fi connection.",
    "en-US": "If set to Low Data, videos won't play automatically. If set to Don't Allow, videos won't load.\n\nFeatures won't be restricted when using a Wi‑Fi connection.",
    "es-ES": "Si seleccionas \"Consumo bajo\", no se reproducirán vídeos automáticamente. Si seleccionas \"No permitir\", no se cargarán vídeos.\n\nEsta función no estará restringida cuando se utilice una conexión Wi-Fi.",
    "es-MX": "Si seleccionas \"Consumo bajo\", no se reproducirán videos automáticamente. Si seleccionas \"No permitir\", no se cargarán videos.\n\nEsta función no estará restringida cuando se utilice una conexión Wi-Fi.",
    "fr-CA": "Si vous sélectionnez « Données réduites », les vidéos ne seront pas jouées automatiquement. Si vous sélectionnez « Ne pas autoriser », les vidéos ne seront pas chargées.\n\nAucune restriction ne sera appliquée quand l'appareil est connecté par Wi-Fi.",
    "fr-FR": "Si vous sélectionnez « Données réduites », les vidéos ne seront pas jouées automatiquement. Si vous sélectionnez « Ne pas autoriser », les vidéos ne seront pas chargées.\n\nAucune restriction ne sera appliquée quand l'appareil est connecté par Wi-Fi.",
    "it-IT": "Selezionando \"Utilizzo dati ridotto\", i video non verranno riprodotti automaticamente. Selezionando \"Non autorizzare\", i video non verranno caricati.\n\nSe usi una connessione Wi-Fi, le funzioni non verranno bloccate.",
    "ja-JP": "「省データ」が選択されていると、動画が自動で再生されなくなります。「使用しない」が選択されていると、動画が読み込まれなくなります。\n\nWi-Fi接続時は機能は制限されません。",
    "ko-KR": "「데이터 절약」을 선택하면 동영상이 자동 재생되지 않습니다. 「사용 안 함」을 선택하면 동영상이 로딩되지 않습니다.\n\nWi-Fi 접속 시에는 기능이 제한되지 않습니다.",
    "nl-NL": "Als je LAAG DATAVERBRUIK kiest, worden video's niet automatisch afgespeeld. Als je NIET TOESTAAN kiest, worden video's niet geladen.\n\nDeze functies worden niet beperkt wanneer je gebruikmaakt van wifi.",
    "pt-PT": "Se selecionares \"Consumo baixo\", os vídeos não serão reproduzidos automaticamente. Se selecionares \"Não permitir\", os vídeos não serão carregados.\n\nEstas funcionalidades não estarão restringidas quando usares uma ligação por Wi-Fi.",
    "ru-RU": "Если выбран вариант Малый расход данных, видео не будут воспроизводиться автоматически. Если выбран вариант Не разрешать, видео не будут загружаться.\n\nФункции не будут ограничиваться при использовании подключения Wi-Fi.",
    "zh-CN": "选择“节省流量”后，视频将不会自动播放。选择“不使用”后，将无法读取视频。\n\n使用Wi-Fi连接时，功能不会受到限制。",
    "zh-TW": "若選擇「低數據」，將不會自動播放影片。若選擇「不使用」，將無法載入影片。\n\n連接Wi-Fi時，則不會對功能進行限制。"
  },
