  "FriendRequest_Dialog_Alert_Save_QR_Message": {
    "de-DE": "Jeder, mit dem du den QR-Code teilst, kann dir daraufhin eine Freundesanfrage senden.\nDie Community-Richtlinien finden Anwendung. Du findest sie auf der Nintendo-Website. Bitte behandle andere Nutzer während des Spielens online mit Respekt.",
    "en-GB": "Anyone you share the QR Code with will be able to send you a friend request.\n\nThe Community Guidelines apply and can be found on Nintendo's website. Please treat others with respect while playing online.",
    "en-US": "Anyone who has this QR code can send you a friend request.\nThe Community Guidelines apply and can be found on Nintendo's website. Please treat others with respect while playing online.",
    "es-ES": "Cualquier persona con la que compartas el código QR podrá enviarte una solicitud de amistad.\n\nSe aplican las reglas comunitarias, que pueden consultarse en el sitio web de Nintendo. Trata a los demás con respeto cuando juegues en línea.",
    "es-MX": "Cualquier persona con la que compartas el código QR podrá enviarte una solicitud de amistad.\nSe aplican las directrices de la comunidad, que pueden consultarse en el sitio web de Nintendo. Trata a los demás con respeto cuando juegues en línea.",
    "fr-CA": "Toute personne avec qui vous partagez ce QR Code pourra vous envoyer une demande d'ami.\n\nLes règles communautaires, qui peuvent être consultées sur le site de Nintendo, s'appliquent. Faites preuve de respect en toutes circonstances.",
    "fr-FR": "Toute personne avec qui vous partagez ce QR Code pourra vous envoyer une demande d'ami.\n\nLes règles communautaires, consultables sur le site de Nintendo, s'appliquent. Faites preuve de respect en toutes circonstances.",
    "it-IT": "Le persone con cui condividi il codice QR potranno mandarti una richiesta di amicizia.\n\nSi applicano le linee guida relative alla community che si trovano sul sito Nintendo. Ricordati di trattare gli altri con rispetto quando giochi online.",
    "ja-JP": "QRコードを共有した相手は、あなたにフレンド申請を送ることができます。",
    "ko-KR": "QR Code를 공유한 상대는 당신에게 친구 신청을 보낼 수 있습니다.",
    "nl-NL": "Iedereen met wie je de QR-code deelt, kan jou een vriendschapsverzoek sturen.\n\nDe community-richtlijnen zijn van toepassing. Ze kunnen op de website van Nintendo worden ingezien. Ga met respect met anderen om wanneer je online speelt.",
    "pt-PT": "Qualquer pessoa com quem partilhares o código QR poderá enviar-te um pedido de amizade.\n\nAplicam-se as diretrizes comunitárias, disponíveis na página da Nintendo. Trata toda a gente com respeito quando jogares online.",
    "ru-RU": "Все, кому вы предоставите этот QR-код, смогут прислать вам предложение дружбы.\n\nДействуют Правила поведения в сообществе, которые можно найти на веб-сайте Nintendo. Относитесь друг к другу с уважением во время игры онлайн.",
    "zh-CN": "共享QR Code给对方后，对方可以向您发送好友申请。",
    "zh-TW": "分享QR碼後，對方可向您傳送朋友申請。"
  },
