  "Friend_Block_Alert": {
    "de-DE": "Du erhältst keine Freundesanfragen von gesperrten Nutzern und du wirst ihnen auch nicht während des Online-Spiels begegnen. (Dies trifft möglicherweise nicht auf alle Spiele oder Spielmodi zu.)",
    "en-GB": "You will not receive friend requests sent to you by blocked users, and you will not encounter those users in online play. (This may not apply to all games or game modes.)",
    "en-US": "You won't get friend requests sent by blocked users, and you won't encounter those users during online play. (This may not apply to all games or game modes.)",
    "es-ES": "Las personas a las que hayas bloqueado no podrán enviarte solicitudes de amistad ni jugar en línea contigo. (Podría haber excepciones en ciertos juegos o modos de juego.)",
    "es-MX": "Los usuarios a los que hayas bloqueado no podrán enviarte solicitudes de amistad ni jugar en línea contigo. (Podría haber excepciones en ciertos juegos o modos de juego).",
    "fr-CA": "Vous ne recevrez pas les demandes d'ami envoyées par les utilisateurs que vous avez bloqués et vous ne les rencontrerez pas en ligne (à l'exception de certains jeux et modes de jeu).",
    "fr-FR": "Vous ne recevrez pas les demandes d'ami envoyées par les utilisateurs que vous avez bloqués et vous ne les rencontrerez pas en ligne (à l'exception de certains jeux et modes de jeu).",
    "it-IT": "Non riceverai richieste di amicizia dagli utenti che hai bloccato e non li incontrerai durante il gioco online. (Alcuni giochi o modalità di gioco potrebbero fare eccezione.)",
    "ja-JP": "ブロックすると、相手からのフレンド申請が届かなくなり､ゲーム内でも出会わなくなります｡(一部のゲームやモードを除きます。)",
    "ko-KR": "차단하면 상대로부터 친구 신청이 도착하지 않으며, 게임 내에서도 만나지 않게 됩니다.(일부 게임이나 모드는 제외됩니다.)",
    "nl-NL": "Geblokkeerde gebruikers kunnen je geen vriendschapsverzoeken sturen, en je komt ze niet tegen als je online speelt. (Dit geldt mogelijk niet voor elke game of gamestand.)",
    "pt-PT": "As pessoas que tiveres bloqueado não poderão enviar-te pedidos de amizade nem jogar online contigo. (Poderá haver exceções em certos jogos ou modos de jogo.)",
    "ru-RU": "Вы не будете получать предложения дружбы, отправленные вам заблокированными пользователями, и не встретитесь с этими пользователями при игре онлайн. (Некоторые игры или режимы игр могут быть исключениями.)",
    "zh-CN": "如果选择加入拒绝列表，将不会收到对方的好友申请，也不会在游戏中碰到对方。（部分游戏和模式除外）",
    "zh-TW": "封鎖後，將不會收到對方的朋友申請，也不會在遊戲中碰面。（部分遊戲和模式除外。）"
  },
