  "Friend_Note_Notice": {
    "de-DE": "Freunde können keine über sie verfassten Notizen einsehen.\nInhalte der Notizen können ebenfalls auf deiner Nintendo Switch 2-/Nintendo Switch-Konsole überprüft und geändert werden.\nFür Notizen können alle auf der Nintendo Switch 2-/Nintendo Switch-Konsole unterstützten Zeichen verwendet werden.",
    "en-GB": "Friends won't be able to see any notes you write about them.\nNote contents can also be checked and edited on your Nintendo Switch 2/Nintendo Switch console.\nNotes can contain any characters supported on Nintendo Switch 2/Nintendo Switch.",
    "en-US": "Friends won't be able to see notes you write about them.\nNotes can also be checked and edited on your Nintendo Switch 2 / Nintendo Switch system.\nNotes can use any characters also supported on Nintendo Switch 2 / Nintendo Switch.",
    "es-ES": "Las otras personas no podrán ver lo que escribas sobre ellas.\nPuedes consultar y editar el nuevo contenido también en tu consola Nintendo Switch 2/Nintendo Switch.\nLas notas pueden contener cualquier carácter que sea válido en Nintendo Switch 2/Nintendo Switch.",
    "es-MX": "Tus amigos no podrán ver nada de lo que escribas.\nTambién puedes consultar y editar este contenido en tu consola Nintendo Switch 2/Nintendo Switch.\nLas notas pueden contener cualquier carácter que sea válido en Nintendo Switch 2/Nintendo Switch.",
    "fr-CA": "Vos amis ne pourront pas lire ce que vous écrivez à leur sujet.\nVos notes sont également accessibles et modifiables depuis une console Nintendo Switch 2/Nintendo Switch, et peuvent contenir tous les caractères compatibles avec ces consoles.",
    "fr-FR": "Vos amis ne pourront pas lire ce que vous écrivez à leur sujet.\nVos mémos sont également accessibles et modifiables depuis une console Nintendo Switch 2/Nintendo Switch, et peuvent contenir tous les caractères compatibles avec ces consoles.",
    "it-IT": "Gli amici non vedranno le note che scrivi su di loro.\nIl contenuto delle note può essere visualizzato e modificato anche sulla tua console Nintendo Switch 2/Nintendo Switch.\nLe note possono contenere qualsiasi carattere supportato su Nintendo Switch 2/Nintendo Switch.\n",
    "ja-JP": "メモの内容は相手には伝わりません。\n入力した内容はSwitch 2 / Switchでも確認と編集ができます。\nSwitch 2 / Switchで入力可能な文字が使えます。",
    "ko-KR": "메모 내용은 상대에게 공유되지 않습니다.\n입력한 내용은 Switch 2 / Switch에서도 확인 및 편집할 수 있습니다.\nSwitch 2 / Switch에서 입력 가능한 문자를 사용할 수 있습니다.",
    "nl-NL": "Vrienden kunnen de notities die je over hen schrijft, niet zien.\nDe inhoud van notities kan ook worden gecontroleerd en aangepast op je Nintendo Switch 2-/Nintendo Switch-systeem.\nJe kunt voor notities alle tekens gebruiken die door het Nintendo Switch 2-/Nintendo Switch-systeem worden ondersteund.",
    "pt-PT": "As outras pessoas não poderão ver o que escreveres sobre elas.\nO conteúdo das notas também pode ser consultado e editado na tua consola Nintendo Switch 2/Nintendo Switch.\nAs notas podem conter todos os caracteres reconhecidos pela Nintendo Switch 2/Nintendo Switch.",
    "ru-RU": "Друзья не увидят ваши заметки. Содержание заметок можно также посмотреть и изменить на вашей консоли Nintendo Switch 2 / Nintendo Switch.\nМожно использовать любые знаки, поддерживаемые консолью Nintendo Switch 2 / Nintendo Switch.",
    "zh-CN": "备注内容不会发送给对方。\n可在Switch 2/Switch上确认和编辑输入的内容。\n可使用Switch 2/Switch上支持的文字。",
    "zh-TW": "對方不會知道備註的內容。\n輸入內容可於Switch 2／Switch上進行確認和編輯。\n能夠使用Switch 2／Switch可輸入的文字。"
  },
