  "LoginError_Label_NA_Agree_Description": {
    "de-DE": "Der Vertrag zum Nintendo-Account und die Datenschutzrichtlinie wurden aktualisiert. Bitte melde dich von deinem Nintendo-Account ab und erneut an, um die aktualisierten Informationen zu sehen.",
    "en-GB": "The Nintendo Account Agreement and Privacy Policy have been updated. Please sign out of your Nintendo Account, then sign in again and view the updated information.",
    "en-US": "The Nintendo Account User Agreement and/or Privacy Policy have been updated. Please sign out and sign in again to view the updated documents.",
    "es-ES": "Se han actualizado los términos del contrato de la cuenta Nintendo y de la política de privacidad. Cierra la sesión de tu cuenta Nintendo y vuelve a iniciarla para consultar la información actualizada.",
    "es-MX": "Se actualizaron los términos del Acuerdo de usuario de la cuenta Nintendo y de la política de privacidad. Cierra la sesión de tu cuenta Nintendo y vuelve a iniciarla para consultar los documentos actualizados.",
    "fr-CA": "Les termes du contrat d'utilisation du compte Nintendo et/ou de la politique de confidentialité ont été mis à jour. Déconnectez-vous, puis connectez-vous à nouveau pour lire les nouveaux termes.",
    "fr-FR": "Les termes du contrat relatif au compte Nintendo et de la politique de confidentialité ont été mis à jour. Déconnectez-vous de votre compte Nintendo, puis connectez-vous à nouveau pour lire les nouveaux termes.",
    "it-IT": "L'Accordo per l'account Nintendo e la Policy sulla privacy sono stati aggiornati. Esci dal tuo account Nintendo, poi accedi nuovamente e leggi le informazioni aggiornate.",
    "ja-JP": "ニンテンドーアカウントの利用規約・プライバシーポリシーが更新されました。一度ログアウトしたあと、再ログインして、新しい利用規約・プライバシーポリシーをご確認ください。",
    "ko-KR": "닌텐도 어카운트 이용 약관・개인정보처리방침이 업데이트되었습니다. 일단 로그아웃한 뒤 다시 로그인하여 새로운 이용 약관・개인정보처리방침을 확인해 주십시오.",
    "nl-NL": "De Nintendo-accountovereenkomst en het privacybeleid zijn bijgewerkt. Log uit van je Nintendo-account, log daarna opnieuw in en lees de bijgewerkte informatie.",
    "pt-PT": "Foram atualizados os termos do Contrato da Conta Nintendo e da Política de Privacidade. Termina a sessão na tua Conta Nintendo, volta a iniciar sessão e consulta as informações atualizadas.",
    "ru-RU": "Соглашение об учетной записи Nintendo и политика конфиденциальности были обновлены. Выйдите из вашей учетной записи Nintendo, затем снова войдите в нее и ознакомьтесь с обновленной информацией.",
    "zh-CN": "Nintendo Account的使用条款・隐私政策已更新。请先登出，然后重新登录，并确认新的使用条款・隐私政策。",
    "zh-TW": "Nintendo Account的使用條款、隱私權政策已經更新。請先登出後重新登入，確認新的使用條款、隱私權政策。"
  },
