  "NSALinkError_Label_Description": {
    "de-DE": "Du kannst deinen Nintendo-Account mit deiner Nintendo Switch 2-/Nintendo Switch-Konsole über die Nutzerseite in der Konsole selbst verknüpfen. Wähle dein Nutzersymbol oben links im HOME-Menü der Konsole aus, um die Nutzerseite aufzurufen.",
    "en-GB": "You can link your Nintendo Switch 2/Nintendo Switch console to your Nintendo Account from your user page on the console itself. To access your user page, select your user icon in the top-left corner of the console's HOME Menu.",
    "en-US": "You can link your Nintendo Switch 2 or Nintendo Switch system to your Nintendo Account from your user page on the system. To access your user page, go to the HOME Menu on your system and select your user icon from the top-left corner.",
    "es-ES": "Si quieres vincular tu cuenta Nintendo a tu consola Nintendo Switch 2/Nintendo Switch, abre el menú HOME de la consola y selecciona tu icono de usuario, situado en la esquina superior izquierda, para acceder a tu página personal.",
    "es-MX": "Si quieres vincular tu cuenta Nintendo a tu consola Nintendo Switch 2 o Nintendo Switch, abre el menú HOME de la consola y selecciona tu ícono de usuario, situado en la esquina superior izquierda, para acceder a tu página personal.",
    "fr-CA": "Vous pouvez associer votre compte Nintendo à une console Nintendo Switch 2/Nintendo Switch depuis votre page d'utilisateur sur la console. Pour accéder à cette page, sélectionnez votre icône d'utilisateur en haut à gauche du menu HOME de la console.",
    "fr-FR": "Vous pouvez associer votre compte Nintendo à une console Nintendo Switch 2/Nintendo Switch depuis votre page d'utilisateur sur la console. Pour accéder à cette page, sélectionnez votre icône d'utilisateur en haut à gauche du menu HOME de la console.",
    "it-IT": "Puoi collegare la tua console Nintendo Switch 2/Nintendo Switch al tuo account Nintendo dalla tua pagina utente sulla console stessa. Per accedere alla tua pagina utente, seleziona la tua icona utente nell'angolo in alto a sinistra del menu HOME della console.",
    "ja-JP": "連携はNintendo Switch 2/Nintendo Switchのマイページからおこなえます。マイページは、ゲーム機のHOMEメニューでユーザーアイコンを選ぶと表示されます。",
    "ko-KR": "연동은 Nintendo Switch 2/Nintendo Switch의 마이 페이지에서 할 수 있습니다. 마이 페이지는 HOME 메뉴에서 유저 아이콘을 선택하면 표시됩니다.",
    "nl-NL": "Je kunt je Nintendo Switch 2-/Nintendo Switch-systeem aan je Nintendo-account koppelen via je gebruikerspagina op het systeem. Kies het gebruikerspictogram linksboven in het HOME-menu van het systeem om naar je gebruikerspagina te gaan.",
    "pt-PT": "Podes vincular a consola Nintendo Switch 2 ou Nintendo Switch à tua Conta Nintendo a partir da tua página de utilizador na própria consola. Para aceder à tua página de utilizador, seleciona o símbolo de utilizador no canto superior esquerdo do menu HOME da consola.",
    "ru-RU": "Вы можете установить связь между консолью Nintendo Switch 2 / Nintendo Switch и учетной записью Nintendo на странице пользователя, выбрав свой значок пользователя в левом верхнем углу в меню HOME на консоли.",
    "zh-CN": "可以从Nintendo Switch 2/Nintendo Switch的我的页面中进行关联。在游戏机的HOME菜单中选择用户头像，就会显示我的页面。",
    "zh-TW": "可以於Nintendo Switch 2／Nintendo Switch的我的頁面中進行連動。選擇HOME選單中的用戶頭像，就會顯示我的頁面。"
  },
