  "Opinion_Notice": {
    "de-DE": "Auf Feedback können wir leider nicht antworten.\nDein Feedback kann von Nintendo ohne eine Gegenleistung an dich und ohne Einschränkung verwendet werden, zum Beispiel auch, um Produkte und Dienstleistungen zu entwickeln und zu verbessern.",
    "en-GB": "Unfortunately, we cannot reply to feedback we receive.\nPlease note that any feedback you do send may be used by Nintendo without compensation to you and without restriction, including to develop and improve our products and services.",
    "en-US": "Please be aware that we don't directly reply to feedback we receive. Also, any feedback you send may be used by Nintendo without compensation to you and without restriction, including to develop and improve our products and services.",
    "es-ES": "No podemos responder a los mensajes que recibamos a través de este formulario.\nNintendo podría utilizar tus comentarios o sugerencias sin compensación ni restricción alguna con el fin de ayudarnos a desarrollar y mejorar nuestros productos y servicios.",
    "es-MX": "Ten en cuenta que no podemos responder a los comentarios que recibimos. Además, Nintendo podría utilizar tus comentarios o sugerencias sin compensación ni restricción alguna con el fin de ayudarnos a desarrollar y mejorar nuestros productos y servicios.",
    "fr-CA": "Veuillez noter que nous ne répondons pas individuellement aux avis qui nous sont envoyés.\nVos commentaires ou suggestions peuvent être utilisés par Nintendo sans compensation ou restriction, afin notamment de développer et d'améliorer nos produits et nos services.",
    "fr-FR": "Veuillez noter que nous ne répondons pas individuellement aux avis qui nous sont envoyés.\nVos commentaires ou suggestions peuvent être utilisés par Nintendo sans compensation ou restriction, afin notamment de développer et d'améliorer nos produits et nos services.",
    "it-IT": "Purtroppo non possiamo rispondere ai commenti che riceviamo.\nI tuoi commenti o suggerimenti potrebbero venire utilizzati da Nintendo senza compensazione o restrizione, allo scopo di sviluppare e migliorare i nostri prodotti e servizi.",
    "ja-JP": "いただいたご意見・ご要望への返信は行っていません。 お客様からいただいたご意見・ご要望は、無償かつ何の制約もなく、当社により製品・サービスの開発や改善などに利用される場合があります。",
    "ko-KR": "보내 주신 의견 및 요청에 대한 답변은 하지 않습니다. 고객님께서 보내 주신 의견 및 요청은 보상이나 제약 없이 당사에 의해 제품, 서비스의 개발 및 개선에 이용될 수 있습니다.",
    "nl-NL": "Helaas kunnen we niet reageren op ontvangen feedback.\nJe feedback kan door Nintendo worden gebruikt zonder compensatie aan jou en zonder beperkingen, waaronder voor de ontwikkeling en verbetering van onze producten en diensten.",
    "pt-PT": "Infelizmente, não nos é possível responder às opiniões recebidas.\nTem em conta que a Nintendo poderá utilizar as opiniões que enviares sem qualquer compensação em troca e sem restrições, com o objetivo de desenvolver e melhorar os seus produtos e serviços.",
    "ru-RU": "К сожалению, у нас нет возможности отвечать на полученные отзывы.\nПримите к сведению, что компания Nintendo может использовать отправленные вами отзывы без компенсации вам и без ограничений, в том числе с целью разработки и улучшения наших продуктов и сервисов.",
    "zh-CN": "对于收到的意见和建议，我们将不予回复。\n您的意见和要求可能会被我们免费且无限制地用于开发和改进我们的产品和服务。",
    "zh-TW": "我們將不會對收到的意見、建議進行回覆。客人提供的意見及建議，有可能在免費且毫無規約的情況下用於開發或改善本公司的商品及服務。"
  },
