    "ja-JP": "付近のデバイスへのアクセスを許可すると、ボイスチャットでBluetoothヘッドセットを利用できます。",
    "ko-KR": "근처 기기에 대한 액세스 권한을 허용하면 보이스챗에서 Bluetooth 헤드셋을 이용할 수 있습니다",
    "nl-NL": "Je kunt een Bluetooth-headset gebruiken voor voicechat als je toegang tot apparaten in de buurt inschakelt.",
    "pt-PT": "Se ativares o acesso aos dispositivos próximos, poderás utilizar uns auriculares com Bluetooth para o chat de voz.",
