  "Other_Label_Online_Status_Description": {
    "de-DE": "Du kannst festlegen, ob deine Freunde deinen Onlinestatus sehen können. Allerdings kannst du möglicherweise nicht mit Freunden online spielen, die deinen Onlinestatus nicht sehen können. Eine Anpassung hier beeinflusst auch die Einstellungen deiner Konsole.",
    "en-GB": "You can set whether or not your friends can see your online status. However, you may not be able to play online with friends who cannot see your online status.\nThis setting is linked to your console.",
    "en-US": "You can set who can see your online status. Friends who can't see your online status may not be able to join you during online play. Changing the setting here will update the setting on your system.",
    "es-ES": "Puedes mostrar u ocultar tu estado de conexión a tus amigos. No obstante, quizá no puedas jugar en línea con aquellos amigos que no puedan ver si estás en línea o no. Este ajuste está vinculado a tu consola.",
    "es-MX": "Puedes cambiar quiénes pueden ver tu estado de conexión. Toma en cuenta que es posible que no puedas jugar en línea con alguien que no pueda ver si estás en línea o no. Este ajuste está vinculado a tu consola.",
    "fr-CA": "Vous pouvez permettre aux personnes de votre liste d'amis de voir votre statut de connexion. Cependant, vous ne pourrez peut-être pas jouer en ligne avec les personnes qui ne peuvent pas voir votre statut. Ce paramètre est lié à votre console.",
    "fr-FR": "Vous pouvez permettre aux personnes de votre liste d'amis de voir votre statut de connexion. Cependant, vous ne pourrez peut-être pas jouer en ligne avec les personnes qui ne peuvent pas voir votre statut. Ce paramètre est lié à votre console.",
    "it-IT": "Puoi decidere se mostrare o meno il tuo stato online agli amici. Tieni presente che potrebbe non essere possibile giocare online con gli amici che non possono vedere il tuo stato online. Questa impostazione è collegata alla tua console.",
    "ja-JP": "フレンドにあなたのオンライン状況を公開するか設定できます。\n公開していない相手とは、オンラインプレイできなくなることがあります。\nこの設定は、ゲーム機本体と連動します。",
    "ko-KR": "친구에게 당신의 온라인 상태를 공개할지 설정할 수 있습니다.\n공개하지 않은 상대와는 온라인 플레이를 하지 못할 수 있습니다.\n이 설정은 게임기 본체와 연동됩니다.",
    "nl-NL": "Je kunt instellen of je vrienden kunnen zien wanneer je online bent. Je kunt echter mogelijk niet online spelen met vrienden die niet kunnen zien of je online bent. Deze instelling is gekoppeld aan je systeem.",
    "pt-PT": "Podes definir se queres mostrar ou ocultar dos teus amigos o teu estado online. No entanto, poderá não ser possível jogar online com amigos que não consigam ver o teu estado online. Esta definição está vinculada à tua consola.",
    "ru-RU": "Вы можете указать, показывать ли ваш онлайн-статус друзьям. Однако вы, вероятно, не сможете играть онлайн с друзьями, которые не могут видеть ваш онлайн-статус. Эта настройка изменится и на вашей консоли.",
    "zh-CN": "可以设置向好友公开您的在线状态｡\n您可能无法和那些未向其公开在线状态的好友一起进行线上游戏｡\n更改此设置，游戏主机上的设置也将一起更改。",
    "zh-TW": "可設定是否要對朋友公開您的線上狀態。\n有可能無法與不公開的對象一起在線上遊玩。\n此項設定將會與遊戲主機連動。"
  },
