  "Other_Label_PowerSaving_Description": {
    "de-DE": "Wenn die Energiesparfunktion von Android (Akku-Leistungsoptimierung) aktiviert ist, stehen Voice-Chats während des Standby-Modus möglicherweise nicht zur Verfügung. Um Voice-Chats während des Standby-Modus nutzen zu können, deaktiviere die Akku-Leistungsoptimierung für diese App.",
    "en-GB": "If the Android power-saving features (battery optimisation) are active, voice chat may not be available during sleep mode. To use voice chat during sleep mode, deactivate battery optimisation for this app.",
    "en-US": "If the Android power-saving features (battery optimization) are active, voice chat may not be available during sleep mode. To use voice chat during sleep mode, deactivate battery optimization for this app.",
    "es-ES": "Si se han activado las funciones de ahorro de batería de Android (optimización de batería), el chat de voz podría no estar disponible mientras el dispositivo esté en modo de espera. Si quieres utilizar el chat de voz durante el modo de espera, desactiva la optimización de batería para esta aplicación.",
    "es-MX": "Si se activaron las funciones de ahorro de batería de Android (optimización de batería), el chat de voz podría no estar disponible mientras el dispositivo esté en modo de espera. Si quieres habilitar el chat de voz, desactiva la optimización de batería para esta aplicación.",
    "fr-CA": "Si la fonction d'économie d'énergie de votre appareil Android est activée, le bavardage vocal peut ne pas être disponible pendant la veille. Pour que le bavardage vocal reste actif quand votre appareil passe en veille, désactivez la fonction d'économie d'énergie pour cette application.",
    "fr-FR": "Si la fonction d'économie d'énergie de votre appareil Android est activée, le chat vocal peut ne pas être disponible pendant la veille. Pour que le chat vocal reste actif quand votre appareil passe en veille, désactivez la fonction d'économie d'énergie pour cette application.",
    "it-IT": "Se la funzione di risparmio energetico (ottimizzazione batteria) di Android è attivata, la chat vocale potrebbe non essere disponibile durante la modalità riposo. Per utilizzare la chat vocale durante la modalità riposo, disattiva l'ottimizzazione della batteria per quest'app.",
    "ja-JP": "Androidの省電力機能（バッテリーの最適化）を使うと、スリープ中にボイスチャットがつづけられない場合があります。スリープ中もボイスチャットをしたいときは、このアプリではバッテリーの最適化をしないように設定してください。",
    "ko-KR": "Android의 절전 기능(배터리 최적화)을 사용하면 슬립 중에 보이스챗을 지속할 수 없는 경우가 있습니다. 슬립 중에도 보이스챗을 이용하고 싶다면 이 앱에서는 배터리 최적화를 하지 않도록 설정해 주십시오.",
    "nl-NL": "Als de energiebesparende functies van Android (accuoptimalisatie) ingeschakeld zijn, is voicechat mogelijk niet te gebruiken in de slaapstand. Om voicechat te kunnen gebruiken in de slaapstand moet de accuoptimalisatie voor deze app worden uitgeschakeld.",
    "pt-PT": "Se as funcionalidades de poupança de energia (otimização da bateria) do teu dispositivo Android estiverem ativas, o chat de voz poderá não estar disponível durante o modo de descanso. Para utilizares o chat de voz durante o modo de descanso, desativa a otimização da bateria para esta aplicação.",
    "ru-RU": "Если функции энергосбережения Android (оптимизация использования батареи) включены, голосовой чат может быть недоступен в режиме ожидания. Для использования голосового чата в режиме ожидания отключите оптимизацию использования батареи для этого приложения.",
    "zh-CN": "使用Android的省电功能（优化电池）后，可能无法在休眠时继续语音聊天。如果想在休眠时进行语音聊天，请在此软件中设置不要使用优化电池。",
    "zh-TW": "如果使用Android的省電功能（電池最佳化），將可能無法在睡眠時繼續語音聊天。如果想在睡眠時也使用語音聊天，請設定此應用程式不要進行電池最佳化。"
  },
