  "Other_Label_PowerSaving_Settings_Off_Description": {
    "de-DE": "Wenn Voice-Chats auch mit den derzeitigen Einstellungen während des Standby-Modus unterbrochen werden, überprüfe bitte die individuellen Energiespareinstellungen für dein Gerät.",
    "en-GB": "If voice chat stops during sleep mode even with the current settings, please check any power-saving settings specific to your device.",
    "en-US": "If voice chat stops during sleep mode even with the current settings, please check any power-saving settings specific to your device.",
    "es-ES": "Si, al utilizar esta configuración, el chat de voz deja de funcionar cuando el dispositivo esté en modo de espera, comprueba los ajustes de ahorro de batería específicos del dispositivo.",
    "es-MX": "Si, al utilizar esta configuración, el chat de voz deja de funcionar cuando el dispositivo esté en modo de espera, comprueba los ajustes de ahorro de batería específicos del dispositivo.",
    "fr-CA": "Si vous constatez une interruption du bavardage lors du passage en veille malgré les réglages actuels, vérifiez tous les paramètres d'économie d'énergie de votre appareil.",
    "fr-FR": "Si vous constatez une interruption du chat vocal lors du passage en veille malgré les réglages actuels, vérifiez tous les paramètres d'économie d'énergie de votre appareil.",
    "it-IT": "Se la chat vocale si interrompe durante la modalità riposo anche con le impostazioni attuali, controlla le impostazioni di risparmio energetico specifiche del tuo dispositivo.",
    "ja-JP": "この設定にしてもスリープ中にボイスチャットが切れてしまうときは、お使いのスマートフォン独自の省電力設定を確認してください。",
    "ko-KR": "이 설정에서도 슬립 중에 보이스챗이 끊어질 경우, 사용하시는 스마트폰의 독자적인 절전 설정을 확인해 주십시오.",
    "nl-NL": "Als voicechat met de huidige instellingen nog steeds niet te gebruiken is in de slaapstand, controleer dan of je apparaat nog andere energiebesparende functies heeft.",
    "pt-PT": "Se, mesmo com a configuração atual, houver uma interrupção do chat de voz durante o modo de descanso, verifica as definições de poupança de energia do teu dispositivo.",
    "ru-RU": "Если голосовой чат прерывается в режиме ожидания даже с текущими настройками, проверьте все настройки энергосбережения, имеющиеся на вашем устройстве.",
    "zh-CN": "如果进行此设置后，语音聊天在休眠时仍断开，请确认您的智能手机自身的省电设置。",
    "zh-TW": "如果進行設定後，睡眠時語音聊天還是會中斷，請確認您的智慧型手機本身的省電設定。"
  },
