  "PlayActivity_Settings_Notice": {
    "de-DE": "Wenn du dich entschließt, einigen Nutzern deine Spielaktivitäten zugänglich zu machen, können sie sehen, wie lange du einen Softwaretitel gespielt hast und wann du ihn zum ersten Mal gespielt hast.\nEine Anpassung hier beeinflusst auch die Einstellungen deiner Konsole.",
    "en-GB": "If you choose to make your play activity visible to some users, they will be able to see how long you've spent playing each software, as well as information about when you played it for the first time.\nThis setting is linked to your console.",
    "en-US": "If you choose to make your play activity visible to some users, they'll be able to see how long you've spent playing each game, as well as information about when you first played them.\nThis setting is linked to your system.",
    "es-ES": "Los usuarios a los que permitas consultar tu historial de programas usados podrán ver cuánto tiempo has utilizado cada programa, además de las fechas en las que jugaste a ellos por primera vez.\nEste ajuste está vinculado a tu consola.",
    "es-MX": "Los usuarios a los que permitas consultar tu historial de juego podrán ver cuánto tiempo has utilizado cada programa, además de las fechas en que los jugaste por primera vez.\nEste ajuste está vinculado a tu consola.",
    "fr-CA": "Si vous décidez de montrer votre historique de jeu à certains utilisateurs, ils pourront voir le temps que vous avez passé sur chaque logiciel, ainsi que la date à laquelle vous l'avez utilisé pour la première fois.\nCe paramètre est lié à votre console.",
    "fr-FR": "Si vous décidez de montrer votre historique de jeu à certains utilisateurs, ils pourront voir le temps que vous avez passé sur chaque logiciel, ainsi que la date à laquelle vous l'avez utilisé pour la première fois.\nCe paramètre est lié à votre console.",
    "it-IT": "Se scegli di mostrare la tua attività di gioco ad altri utenti, questi potranno vedere per quanto tempo hai usato ogni software e quando l'hai avviato per la prima volta.\nQuesta impostazione è collegata alla tua console.",
    "ja-JP": "公開した相手のゲーム機本体上などに、あなたのソフトのプレイ時間やプレイしはじめた日時が表示されます｡\nこの設定は、ゲーム機本体と連動します。",
    "ko-KR": "공개한 상대의 게임기 본체 등에, 당신의 소프트웨어 플레이 시간이나 플레이를 시작한 일시가 표시됩니다.\n이 설정은 게임기 본체와 연동됩니다.",
    "nl-NL": "Als je je overzicht van gespeelde software zichtbaar maakt voor andere gebruikers, kunnen ze zien hoelang je elke software hebt gespeeld, en krijgen ze informatie over wanneer je die software voor het eerst hebt gespeeld.\nDeze instelling is gekoppeld aan je systeem.",
    "pt-PT": "Se optares por mostrar a tua atividade de jogo a outros utilizadores, estes poderão ver quanto tempo utilizaste cada uma, assim como as datas em que as começaste a utilizar pela primeira vez.\nEsta definição está vinculada à tua consola.",
    "ru-RU": "Если вы решите разрешить каким-либо пользователям видеть ваши игровые действия, они будут видеть, как долго вы использовали каждую программу, а также когда вы использовали ее впервые.\nЭта настройка изменится и на вашей консоли.",
    "zh-CN": "您的软件游玩时间以及游戏开始日期会显示在已向其公开的用户的游戏主机上。\n此设置将与游戏主机联动。",
    "zh-TW": "您軟體的遊玩時間和首次遊玩時間將會在諸如公開對象的遊戲主機上等地方顯示。\n此設定與遊戲主機連動。"
  },
