const translatedTextSource = new WeakMap();
const translatedAttributeSource = new WeakMap();
let languageObserver = null;

function normalizeAppLocale(value) {
    const raw = String(value || '').trim().replace(/_/g, '-');
    if (!raw) return null;
    const exact = APP_SUPPORTED_LOCALES.find((locale) => locale.toLowerCase() === raw.toLowerCase());
    if (exact) return exact;
    const lower = raw.toLowerCase();
    if (lower.startsWith('zh-hant') || lower === 'zh-tw' || lower === 'zh-hk' || lower === 'zh-mo') return 'zh-TW';
    if (lower.startsWith('zh')) return 'zh-CN';
    const language = lower.split('-')[0];
    return { de: 'de-DE', en: 'en-GB', es: 'es-ES', fr: 'fr-FR', it: 'it-IT', ja: 'ja-JP', ko: 'ko-KR', nl: 'nl-NL', pt: 'pt-PT', ru: 'ru-RU' }[language] || null;
}
let localizationAccountUser = null;

function localizationSetting(key, fallback = '') {
    try {
        const cache = JSON.parse(localStorage.getItem('nso_official_user_settings_v1') || '{}');
        if (cache && typeof cache === 'object' && Object.prototype.hasOwnProperty.call(cache, key)) {
            return String(cache[key]);
        }
        const legacy = localStorage.getItem(`nso_official_${key}`);
        return legacy == null ? fallback : String(legacy);
    } catch {
        return fallback;
    }
}

function sessionLocalizationUser() {
    if (localizationAccountUser) return localizationAccountUser;
    try { return userSession?.result?.user || userSession?.user || null; } catch { return null; }
}

function accountAppLocale() {
    const user = sessionLocalizationUser() || {};
    return normalizeAppLocale(user.language || user.locale || user.naLanguage);
}

function currentAppLocale() {
    const preference = localizationSetting('language', 'account');
    if (preference === 'account') return accountAppLocale() || normalizeAppLocale(navigator.language) || 'en-GB';
    return normalizeAppLocale(preference) || accountAppLocale() || normalizeAppLocale(navigator.language) || 'en-GB';
}
